  ccxt::any parseMarket(ccxt::any market) override {
    //
    //   {
    //       "instrument_id":"149264164756389888",
    //       "instrument_uuid":"e9360798-6a10-45d6-af05-67c30eb91e2d",
    //       "symbol":"ETH-PERP",
    //       "type":"PERP",
    //       "base_asset_id":"118059611793145856",
    //       "base_asset_uuid":"d85dce9b-5b73-5c3c-8978-522ce1d1c1b4",
    //       "base_asset_name":"ETH",
    //       "quote_asset_id":"1",
    //       "quote_asset_uuid":"2b92315d-eab7-5bef-84fa-089a131333f5",
    //       "quote_asset_name":"USDC",
    //       "base_increment":"0.0001",
    //       "quote_increment":"0.01",
    //       "price_band_percent":"0.02",
    //       "market_order_percent":"0.0075",
    //       "qty_24hr":"44434.8131",
    //       "notional_24hr":"110943454.279785",
    //       "avg_daily_qty":"1099171.6025",
    //       "avg_daily_notional":"2637240145.456987",
    //       "previous_day_qty":"78909.3939",
    //       "open_interest":"1270.749",
    //       "position_limit_qty":"1831.9527",
    //       "position_limit_adq_pct":"0.05",
    //       "replacement_cost":"0.23",
    //       "base_imf":"0.1",
    //       "min_notional_value":"10",
    //       "funding_interval":"3600000000000",
    //       "trading_state":"TRADING",
    //       "quote":{
    //          "best_bid_price":"2490.8",
    //          "best_bid_size":"9.0515",
    //          "best_ask_price":"2490.81",
    //          "best_ask_size":"4.8486",
    //          "trade_price":"2490.39",
    //          "trade_qty":"0.9508",
    //          "index_price":"2490.5",
    //          "mark_price":"2490.8",
    //          "settlement_price":"2490.81",
    //          "limit_up":"2615.42",
    //          "limit_down":"2366.34",
    //          "predicted_funding":"0.000009",
    //          "timestamp":"2024-02-10T16:07:39.454Z"
    //       }
    //    }
    //
    ccxt::any marketId = this->safeString(market, std::string("symbol"));
    ccxt::any baseId = this->safeString(market, std::string("base_asset_name"));
    ccxt::any quoteId =
        this->safeString(market, std::string("quote_asset_name"));
    ccxt::any typeId =
        this->safeString(market, std::string("type")); // 'SPOT', 'PERP'
    ccxt::any isSpot = (isEqual(typeId, std::string("SPOT")));
    ccxt::any fees = this->fees;
    ccxt::any symbol = add(add(baseId, std::string("/")), quoteId);
    ccxt::any settleId = ccxt::any{};
    if (!isTrue(isSpot)) {
      settleId = quoteId;
      symbol = add(symbol, add(std::string(":"), quoteId));
    }
    ccxt::any isLinear =
        (isTrue(isSpot) ? ccxt::any(ccxt::any{})
                        : ccxt::any((isEqual(settleId, quoteId))));
    ccxt::any isInverse =
        (isTrue(isSpot) ? ccxt::any(ccxt::any{})
                        : ccxt::any((!isEqual(settleId, quoteId))));
    if (isTrue(isEqual(marketId, ccxt::any{}))) {
      throw ExchangeError(toString(
          add(this->id, std::string(" parseMarket() missing marketId"))));
    }
    return this->safeMarketStructure(ccxt::dict{
        {std::string("id"), marketId},
        {std::string("lowercaseId"), toLowerCase(marketId)},
        {std::string("symbol"), symbol},
        {std::string("base"), baseId},
        {std::string("quote"), quoteId},
        {std::string("settle"), settleId},
        {std::string("baseId"), baseId},
        {std::string("quoteId"), quoteId},
        {std::string("settleId"), settleId},
        {std::string("type"),
         (isTrue(isSpot) ? ccxt::any(std::string("spot"))
                         : ccxt::any(std::string("swap")))},
        {std::string("spot"), isSpot},
        {std::string("margin"), false},
        {std::string("swap"), !isTrue(isSpot)},
        {std::string("future"), false},
        {std::string("option"), false},
        {std::string("active"),
         isEqual(this->safeString(market, std::string("trading_state")),
                 std::string("TRADING"))},
        {std::string("contract"), !isTrue(isSpot)},
        {std::string("linear"), isLinear},
        {std::string("inverse"), isInverse},
        {std::string("taker"),
         ::getValue(::getValue(fees, std::string("trading")),
                    std::string("taker"))},
        {std::string("maker"),
         ::getValue(::getValue(fees, std::string("trading")),
                    std::string("maker"))},
        {std::string("contractSize"),
         (isTrue(isSpot) ? ccxt::any(ccxt::any{}) : ccxt::any(1))},
        {std::string("expiry"), ccxt::any{}},
        {std::string("expiryDatetime"), ccxt::any{}},
        {std::string("strike"), ccxt::any{}},
        {std::string("optionType"), ccxt::any{}},
        {std::string("precision"),
         ccxt::dict{
             {std::string("amount"),
              this->safeNumber(market, std::string("base_increment"))},
             {std::string("price"),
              this->safeNumber(market, std::string("quote_increment"))},
             {std::string("cost"),
              this->safeNumber(market, std::string("quote_increment"))},
         }},
        {std::string("limits"),
         ccxt::dict{
             {std::string("leverage"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"),
                   this->safeNumber(market, std::string("base_imf"))},
              }},
             {std::string("amount"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"),
                   (isTrue(isSpot)
                        ? ccxt::any(ccxt::any{})
                        : ccxt::any(this->safeNumber(
                              market, std::string("position_limit_qty"))))},
              }},
             {std::string("price"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
             {std::string("cost"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(market, std::string("min_notional_value"))},
                  {std::string("max"), ccxt::any{}},
              }},
         }},
        {std::string("info"), market},
        {std::string("created"), ccxt::any{}},
    });
  }

